import zipfile,re,sys
z=zipfile.ZipFile(sys.argv[1])
wb=z.read('xl/workbook.xml').decode()
for m in re.finditer(r'<definedName[^>]*name="([^"]+)"[^>]*>([^<]*)</definedName>',wb):
    if any(k in m.group(1) for k in ('Export','Path','cs_')) or 'Ref' in m.group(2): print(m.group(1),'=',m.group(2))
sheets=re.findall(r'<sheet [^>]*name="([^"]+)"[^>]*r:id="([^"]+)"',wb)
rels=z.read('xl/_rels/workbook.xml.rels').decode()
rmap=dict(re.findall(r'Id="([^"]+)"[^>]*Target="([^"]+)"',rels)) or {}
rmap.update({a:b for b,a in re.findall(r'Target="([^"]+)"[^>]*Id="([^"]+)"',rels)})
print('SHEETS',[s for s,_ in sheets])
for s,rid in sheets:
    if s=='Ref':
        x=z.read('xl/'+rmap[rid].lstrip('/').replace('xl/','')).decode()
        for c in re.finditer(r'<c r="([A-Z]+[0-9]+)"[^>]*>(.*?)</c>',x):
            if re.match(r'[A-F][1-9]$',c.group(1)): print(c.group(1),c.group(2)[:400])
print('calcPr', re.findall(r'<calcPr[^>]*/>',wb))
print('fileSharing/workbookPr', re.findall(r'<(?:workbookPr|fileSharing)[^>]*/>',wb))
EOF
"C:/Users/eric_rash/.local/bin/uv.exe" run --no-project python "$T/names.py" "$T/VB.xlsx"

