param([string]$Path,[string]$Extra='')
$xl = New-Object -ComObject Excel.Application; $xl.Visible=$false; $xl.DisplayAlerts=$false
try {
  $wb = $xl.Workbooks.Open($Path)
  $raw = [IO.File]::ReadAllText('C:\Users\eric_rash\.claude\jobs\8f18aaef\tmp\rawdatafiles.m')
  $has = $false; foreach($q in $wb.Queries){ if($q.Name -eq 'Raw Data Files'){ $has=$true } }
  if ($has) { $wb.Queries.Item('Raw Data Files').Formula = $raw } else {
    $null = $wb.Queries.Add('Raw Data Files', $raw)
    $pat = '(?s)    // Resolve the export folder.*?Folder\.Files\(Fallbacks\{1\}\),'
    foreach ($n in 'Kinexon Master','Sample File') { $q=$wb.Queries.Item($n); $q.Formula = [regex]::Replace($q.Formula,$pat,'    Source = #"Raw Data Files",') }
  }
  $m = @"
let
  users = try Table.RowCount(Folder.Contents("C:\Users")) otherwise -1,
  r1 = try #"Raw Data Files",
  a = if r1[HasError] then "RAW ERR: " & r1[Error][Message] & " | " & Text.From(r1[Error][Detail]?) else "RAW rows=" & Text.From(Table.RowCount(r1[Value])) & " first=" & r1[Value]{0}[Name] & " cols=" & Text.Combine(Table.ColumnNames(r1[Value]), ","),
  r2 = try #"Kinexon Master",
  b = if r2[HasError] then "KM ERR: " & r2[Error][Message] else "KM rows=" & Text.From(Table.RowCount(r2[Value]))
in
  #table({"out"}, {{"users=" & Text.From(users)}, {a}, {b}})
"@
  $null = $wb.Queries.Add('Dbg', $m)
  $ws = $wb.Worksheets.Add()
  $lo = $ws.ListObjects.Add(0, 'OLEDB;Provider=Microsoft.Mashup.OleDb.1;Data Source=$Workbook$;Location=Dbg;Extended Properties=""', [Type]::Missing, 1, $ws.Range('A1'))
  $lo.QueryTable.CommandType = 2; $lo.QueryTable.CommandText = 'SELECT * FROM [Dbg]'; $lo.QueryTable.BackgroundQuery=$false
  try { $lo.QueryTable.Refresh($false) | Out-Null } catch { "DBG REFRESH FAILED: " + $_.Exception.Message }
  for($i=2;$i -le 4;$i++){ $ws.Cells.Item($i,1).Text }
  $wb.Close($false)
} finally { $xl.Quit() }

